import React, { memo, useEffect, useMemo, useState } from "react";
import { Redirect, Route, Router, Switch, useHistory, useParams } from "react-router-dom";
import utils from "./utils";
import Layout from "./layout";
import lazyload from "./utils/lazyload";
import { useObserver } from "mobx-react-lite";
import user from "./store/user"
import useRoute, { mainRoutes } from "./routes";
import config from "config";
import language from "./locales";
import './style/global.less';
import { IRoute } from "./types/route";
import PageRouteLayout from "./components/system/PageRoute/Layout";
import { ConfigProvider } from "@arco-design/web-react";


const arcoLocals = import.meta.glob('./../node_modules/@arco-design/web-react/es/locale/**.js')

function getFlattenRoutes(routes: IRoute[]) {
    const mod = import.meta.glob('./pages/**/[a-z[]*.tsx');
    const res = [];
    function travel(_routes: IRoute[]) {
      _routes.forEach((route) => {
        if(route.isLayout){
            // 布局
            if(route.children) route.children = getFlattenRoutes(route.children);
            const layoutRoute = { ...route };
            route.component = (props) => (
                <PageRouteLayout
                    {...props}
                    route={layoutRoute}
                />
            )
        }else {
            if(!route.component) route.component = lazyload(mod[`./pages/${route.key}/index.tsx`]);
            if (Array.isArray(route.children) && route.children.length) {
                travel(route.children);
            }
        }
        res.push(route);
      });
    }
    travel(routes);
    return res;
}

  

export const App = () => {

    const [routes, defaultRoute] = useRoute(user.permissions, mainRoutes);


    const flattenRoutes = useMemo(() => getFlattenRoutes(routes), [])


    const routeChildren = useMemo(() => {
        return flattenRoutes.map((route, index) => {
            return (
                <Route
                    key={index}
                    exact={route.path == '*'? false : !route.isLayout}
                    path={route.path}
                    component={route.component}
                />
            );
        })
    },[flattenRoutes])



    return useObserver(() => {


        const { lang } = language;


        const componentConfig = useMemo(() => {
            return {
              Card: {
                bordered: false,
              },
              List: {
                bordered: false,
              },
              Modal: {
                maskClosable: false,
                escToExit: false,
              },
              Table: {
                border: false,
              },
            }
        },[])

        const [locale, setLocale] = useState();

        useEffect(() => {
            if(lang) {
                const resultFun = arcoLocals[`./../node_modules/@arco-design/web-react/es/locale/${lang}.js`];
                if(resultFun){
                    resultFun().then((res) => {
                        setLocale(res.default);
                    })
                }
            }
        },[lang])
        

        if(!locale) return null;
        
        console.log('lang', lang)
    
        return (
            <ConfigProvider
                locale={locale}
                componentConfig={componentConfig}
            >
                <Router history={utils.history} key={lang}>
                    <Switch>
                        <Route path={`${config.admin_path}*`} component={Layout}/>
                        <Route path={config.login_path} component={lazyload(() => import('./manages/login/index'))} />
                        {routeChildren}
                        <Route exact path="/">
                            <Redirect to={defaultRoute} />
                        </Route>
                    </Switch>
                </Router>
            </ConfigProvider>
        )
    })
}
