import { IRoute } from "@/types/route";
import lazyload from "../utils/lazyload";
import qs from 'query-string';
import React, { memo, useEffect, useMemo, useRef, useState } from "react";
import { observer } from 'mobx-react-lite';
import { Breadcrumb, Layout, Menu, Modal, Spin } from "@arco-design/web-react";
import Navbar from '../components/system/NavBar';
import classNames from "classnames";
import { HashRouter, Redirect, Route, Switch, useHistory, useRouteMatch, useLocation } from "react-router-dom";
import styles from './index.module.less';
import i18next from 'i18next';
import _ from "lodash";
import user from "../store/user";
import { toJS } from "mobx";
import useRoute, { adminRoutes } from "../routes";
import NotLogin from "@system/NotLogin";
import { IconDashboard } from "@arco-design/web-react/icon";
import config from '../../config';


const SubMenu = Menu.SubMenu;

const Sider = Layout.Sider;
const Content = Layout.Content;
const Footer = Layout.Footer;

function getIconFromKey(key) {
    switch (key) {
      case 'dashboard':
        return <IconDashboard  />;
      default:
        return null
    }
}

function getFlattenRoutes(routes) {
    const mod = import.meta.glob('../manages/**/[a-z[]*.tsx');
    const res = [];
    function travel(_routes) {
      _routes.forEach((route) => {
        if (Array.isArray(route.children) && route.children.length) {
          travel(route.children);
        }
        if(!route.component) route.component = lazyload(mod[`../manages/${route.key}/index.tsx`]);
        res.push(route);
      });
    }
    travel(toJS(routes));
    return res;
}



const PageLayout = (props) => {


    const showNavbar = true;
    const showMenu = true;
    const showFooter = true;
    const history = useHistory();
    const pathname = history.location.pathname;
    const currentComponent = qs.parseUrl(pathname).url

    const [routes, defaultRoute] = useRoute(user.permissions, adminRoutes);


    const [breadcrumb, setBreadCrumb] = useState([]);
    const [collapsed, setCollapsed] = useState<boolean>(false);
    const menuWidth = collapsed ? 48 : 220;

    const paths = (currentComponent || defaultRoute).split('/');
    const defaultOpenKeys = paths.slice(0, paths.length - 1);
    const [openKeys, setOpenKeys] = useState<string[]>(() => [defaultOpenKeys.join('/')]);

    function onClickMenuItem(key) {
        history.push(key);
    }

    const flattenRoutes = useMemo(() => getFlattenRoutes(routes) || [], [routes]);
    const routeChildren = useMemo(() => {
        return flattenRoutes.map((route, index) => {
            return (
                <Route
                    key={index}
                    path={config.admin_path + route.path}
                    component={route.component}
                />
            );
        })
    },[flattenRoutes])



    const routeMap = useRef<Map<string, React.ReactNode[]>>(new Map());
    const menuMap = useRef<
        Map<string, { menuItem?: boolean; subMenu?: boolean }>
    >(new Map());

    function toggleCollapse() {
        setCollapsed((collapsed) => !collapsed);
    }


    function renderRoutes(locale) {
        routeMap.current.clear();
        return function travel(_routes: IRoute[], level, parentNode = []) {
            return _routes.map((route) => {
                const { breadcrumb = true, ignore } = route;
                const path = config.admin_path + route.path;
                const iconDom = route.icon || getIconFromKey(route.key);
                const titleDom = (
                    <>
                        {iconDom} {locale(route.name)} 
                    </>
                );

                const breadcrumbList = iconDom? [iconDom, route.name] : [route.name];
                routeMap.current.set(
                    path,
                    breadcrumb ? [...parentNode, ...breadcrumbList] : []
                );

                const visibleChildren = (route.children || []).filter((child) => {
                    const { ignore, breadcrumb = true } = child;
                    if (ignore || breadcrumb) {
                        routeMap.current.set(
                            child.path,
                            breadcrumb ? [...parentNode, route.name, child.name] : []
                        );
                    }

                    return !ignore;
                });

                if (ignore) {
                    return '';
                }
                if (visibleChildren.length) {
                    menuMap.current.set(route.key, { subMenu: true });
                    return (
                        <SubMenu key={path} title={titleDom}>
                            {travel(
                                visibleChildren,
                                level + 1, 
                                [
                                    ...parentNode,
                                    ...breadcrumbList
                                ]
                            )}
                        </SubMenu>
                    );
                }
                menuMap.current.set(route.key, { menuItem: true });
                return <Menu.Item key={path}>{titleDom}</Menu.Item>;
            });
        };
    }

    const menuChildren = useMemo(() => {
        return renderRoutes(i18next.t)(routes, 1);
    },[routes])


    useEffect(() => {
        const routeConfig = routeMap.current.get(pathname);
        setBreadCrumb(routeConfig || []);
    },[pathname])

    if(!user.isLogin){
        
        return <NotLogin />
    }

    return (
        <Layout className={styles.layout}>
            <div
                className={classNames(styles['layout-navbar'], {
                    [styles['layout-navbar-hidden']]: !showNavbar,
                })}
            >
                <Navbar show={showNavbar} />
            </div>
            <Layout>
                {showMenu && (
                    <Sider
                        className={styles['layout-sider']}
                        width={menuWidth}
                        collapsed={collapsed}
                        onCollapse={setCollapsed}
                        trigger={null}
                        collapsible
                        breakpoint="xl"
                    >
                        <Menu
                            collapse={collapsed}
                            className={styles['layout-menu']}
                            onClickMenuItem={onClickMenuItem}
                            defaultSelectedKeys={[currentComponent]}
                            hasCollapseButton
                            onCollapseChange={toggleCollapse}
                            openKeys={openKeys}
                            onClickSubMenu={(_, openKeys) => {
                                setOpenKeys(openKeys);
                            }}
                        >
                            {menuChildren}
                        </Menu>
                    </Sider>
                )}
                <Layout className={styles['layout2']}>
                    {!!breadcrumb.length && (
                        <div className={styles['layout-breadcrumb']}>
                            <Breadcrumb>
                            {breadcrumb.map((node, index) => (
                                <Breadcrumb.Item key={index}>
                                    {typeof node === 'string' ? i18next.t(node) || node : node}
                                </Breadcrumb.Item>
                            ))}
                            </Breadcrumb>
                        </div>
                    )}
                    <Content className={styles['layout-content']}>
                        <div className={styles['layout-content-route']}>
                            <Switch>
                                {routeChildren}
                                <Route exact path="/">
                                    <Redirect to={defaultRoute} />
                                </Route>
                            </Switch>
                        </div>
                    </Content>
                    {showFooter && <Footer />}
                </Layout>
            </Layout>
        </Layout>
    )
}

export default observer(PageLayout)